}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateOpeningImport {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,13}\\.\\d{2}");

    // Every line is checked before any is stored: name,period,amount — the name a person's name or alias on the sheet
    // (ignoring case and surrounding spaces), the period one on the sheet (open or closed), the amount with two decimals,
    // 0.00 or more. Blank lines are skipped; a paste with no line is refused.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody OpeningImportRequest body, People people,
            Periods periods, Out<ImportedOpenings> out) throws InvalidPeriodException {
        String sheet = sheetId.trim();
        String text = body == null || body.text() == null ? "" : body.text();
        List<ImportedOpenings.Line> lines = new ArrayList<>();
        int n = 0;
        for (String line : text.split("\\r?\\n")) {
            n++;
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length != 3) {
                throw new InvalidPeriodException("Line " + n + ": type name,period,amount.");
            }
            String name = fields[0].trim();
            Person person = name.isEmpty() ? null : people.findByName(sheet, name);
            if (person == null) {
                throw new InvalidPeriodException("Line " + n + ": no person " + name + " on this sheet.");
            }
            String periodName = fields[1].trim();
            Period period = periodName.isEmpty() ? null : periods.find(sheet, periodName);
            if (period == null) {
                throw new InvalidPeriodException("Line " + n + ": no period " + periodName + " on this sheet.");
            }
            String amount = fields[2].trim();
            if (!AMOUNT.matcher(amount).matches()) {
                throw new InvalidPeriodException("Line " + n + ": the amount must be 0.00 or more, with two decimals.");
            }
            lines.add(new ImportedOpenings.Line(person, period, new BigDecimal(amount)));
        }
        if (lines.isEmpty()) {
            throw new InvalidPeriodException("Paste at least one line of name,period,amount.");
        }
        out.set(new ImportedOpenings(lines));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SetImportedOpenings {
    // Each checked line adds its amount to the person's opening balance for the period, in order (OPENING_SET). A
    // (soft-)closed period's carried figures stay as fixed; the balance counts once it is reopened and closed again.
    public void set(@PathVariable("sheetId") String sheetId, @Val ImportedOpenings imported, Periods periods,
            ServerHttpConnection connection, Audit audit, Out<OpeningImportResponse> result) {
        String sheet = sheetId.trim();
        String user = Audit.user(connection);
        for (ImportedOpenings.Line line : imported.lines()) {
            periods.addOpening(sheet, line.period().name(), line.person().id(), line.amount());
            audit.record(Audit.line("OPENING_SET", sheet, user, "name=" + line.person().name(),
                    "period=" + line.period().name(), "amount=" + line.amount().toPlainString()));
        }
        result.set(new OpeningImportResponse(imported.lines().size()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.person.Person;

/** Every line of a paste of opening balances, checked, in the order typed. */
public record ImportedOpenings(List<Line> lines) {

    /** A line: the person (found by name or alias), the period and the amount to add to their opening balance for it. */
    public record Line(Person person, Period period, BigDecimal amount) {
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithOpeningImport {
    public void respond(@Val OpeningImportResponse imported, ObjectResponse<OpeningImportResponse> response) {
        response.send(imported);
    }
}
package net.officefloor.hq.app.period;

/** A period action was refused: no such period on the sheet, it is already closed, or (on reopening) it is not closed or the user is not a steward. */
public class PeriodRefusedException extends Exception {

    public PeriodRefusedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandlePeriodRefused {
    public void handle(@Parameter PeriodRefusedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}

